    $id=(int)($item['category_id']??0);$seen=[];
    while($id){if(isset($seen[$id]))throw new RuntimeException('CATEGORY_CYCLE');$seen[$id]=true;$c=$t['item_categories'][$id]??null;if(!$c)break;if((int)($c['inventory_account_id']??0)>0)return[(int)$c['inventory_account_id'],'CATEGORY'];$id=(int)($c['parent_id']??0);}
    $g=$t['item_groups'][$item['group_id']??0]??null;if((int)($g['inventory_account_id']??0)>0)return[(int)$g['inventory_account_id'],'GROUP'];
    return[(int)($t['accounting_settings']['INVENTORY_ACCOUNT']['account_id']??0),'COMPANY_SETTING'];
}
